    $db=obtenerConexion(); $q=$db->prepare('SELECT * FROM sc_pedidos WHERE usuario_id=? ORDER BY creado_en DESC,id DESC'); $q->execute([usuarioId()]); $pedidos=$q->fetchAll();
    $q=$db->prepare('SELECT i.* FROM sc_pedido_items i JOIN sc_pedidos p ON p.id=i.pedido_id WHERE p.usuario_id=? ORDER BY i.id'); $q->execute([usuarioId()]); $lineas=[];
    foreach ($q->fetchAll() as $item) $lineas[$item['pedido_id']][]=$item;
} catch (Throwable $ex) { error_log((string)$ex); $error='No pudimos consultar tus pedidos. Tus datos siguen guardados; comprueba la conexión con MySQL e inténtalo de nuevo.'; }
